function rampartSimulate(createStrategy, seed, maxTicks) {
  var obs = arguments.length > 3 ? arguments[3] : null;
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }
  function mkRoute(pts) {
    var segs = [], len = 0;
    for (var i = 0; i + 1 < pts.length; i++) {
      var ax = pts[i][0] * 100 + 50, ay = pts[i][1] * 100 + 50, bx = pts[i + 1][0] * 100 + 50, by = pts[i + 1][1] * 100 + 50;
      var l = Math.abs(bx - ax) + Math.abs(by - ay);
      segs.push({ x: ax, y: ay, dx: Math.sign(bx - ax), dy: Math.sign(by - ay), start: len, len: l });
      len += l;
    }
    return { segs: segs, len: len };
  }
  var ROUTES = [mkRoute([[0, 2], [6, 2], [6, 10], [12, 10], [12, 3], [18, 3], [18, 11], [23, 11]]),
                mkRoute([[0, 6], [21, 6], [21, 11], [23, 11]])];
  function place(e) {
    var segs = ROUTES[e.air].segs, p = e.progress;
    for (var i = 0; i < segs.length; i++) {
      var s = segs[i];
      if (p <= s.start + s.len || i === segs.length - 1) { e.x = s.x + s.dx * (p - s.start); e.y = s.y + s.dy * (p - s.start); return; }
    }
  }
  var SLOTS = [[3, 3], [5, 5], [7, 4], [7, 8], [9, 9], [10, 5], [11, 8], [13, 8], [14, 5], [15, 2], [16, 7], [17, 4], [19, 8], [20, 10], [22, 9], [3, 7]];
  var TNAMES = ["bolt", "cannon", "frost", "lance", "flak"];
  var TT = {
    bolt: { idx: 0, cost: 50, dmg: 26, period: 8, range: 300, splash: 0, slow: 0, pierce: 0, ground: 1, air: 1 },
    cannon: { idx: 1, cost: 90, dmg: 60, period: 24, range: 260, splash: 90, slow: 0, pierce: 0, ground: 1, air: 0 },
    frost: { idx: 2, cost: 70, dmg: 10, period: 12, range: 240, splash: 0, slow: 30, pierce: 0, ground: 1, air: 1 },
    lance: { idx: 3, cost: 120, dmg: 180, period: 36, range: 360, splash: 0, slow: 0, pierce: 1, ground: 1, air: 0 },
    flak: { idx: 4, cost: 80, dmg: 40, period: 10, range: 320, splash: 70, slow: 0, pierce: 0, ground: 0, air: 1 }
  };
  var ELIST = ["grunt", "runner", "wisp", "brute", "splitter", "mender"];
  var ET = {
    grunt: { hp: 60, speed: 10, bounty: 4, leak: 1, air: 0, first: 1, weight: 10 },
    runner: { hp: 40, speed: 20, bounty: 4, leak: 1, air: 0, first: 2, weight: 4 },
    wisp: { hp: 50, speed: 12, bounty: 6, leak: 2, air: 1, first: 3, weight: 3 },
    brute: { hp: 150, speed: 6, bounty: 9, leak: 3, air: 0, first: 4, weight: 3 },
    splitter: { hp: 90, speed: 8, bounty: 6, leak: 2, air: 0, first: 6, weight: 2 },
    mender: { hp: 70, speed: 8, bounty: 7, leak: 2, air: 0, first: 8, weight: 1 },
    splitling: { hp: 0, speed: 12, bounty: 1, leak: 1, air: 0, first: 0, weight: 0 }
  };
  var rng = mulberry32(seed);
  var mult = [0, 1000];
  function m(w) { while (mult.length <= w) mult.push(Math.floor(mult[mult.length - 1] * 108 / 100)); return mult[w]; }
  function genWave(w) {
    var n = 4 + Math.floor(3 * w / 5), out = [], av = [], sum = 0, i;
    for (i = 0; i < ELIST.length; i++) if (ET[ELIST[i]].first <= w) { av.push(ELIST[i]); sum += ET[ELIST[i]].weight; }
    for (i = 0; i < n; i++) {
      var r = rng() % sum, j = 0;
      while (r >= ET[av[j]].weight) { r -= ET[av[j]].weight; j++; }
      out.push(av[j]);
    }
    return out;
  }
  function view(e) {
    return { id: e.id, type: e.type, hp: e.hp, maxHp: e.maxHp, x: e.x, y: e.y, air: e.air, armor: e.armor, speed: e.speed, slowed: e.slow > 0 ? 1 : 0, remaining: ROUTES[e.air].len - e.progress };
  }
  var strat = createStrategy();
  var hasTarget = strat && typeof strat.target === "function";
  var log = [], gold = 250, baseHp = 10, wave = 0, nextId = 1, fallTick = -1;
  var enemies = [], queue = [], turrets = [];
  for (var si = 0; si < 16; si++) turrets.push(null);
  var nextComp = genWave(1);
  var fx = obs ? [] : null;
  function mkEnemy(type, w, maxHp, progress) {
    var d = ET[type];
    var e = { id: nextId++, type: type, wave: w, hp: maxHp, maxHp: maxHp, progress: progress, age: 0, slow: 0, air: d.air,
      armor: type === "grunt" ? Math.floor(w / 4) : type === "brute" ? 6 + w : 0, speed: d.speed, bounty: d.bounty, leak: d.leak, x: 0, y: 0 };
    place(e);
    enemies.push(e);
    return e;
  }
  function tstats(t) {
    var d = TT[t.type], dmg = d.dmg;
    for (var k = 1; k < t.tier; k++) dmg = Math.floor(dmg * 16 / 10);
    t.dmg = dmg; t.range = d.range + 30 * (t.tier - 1);
  }
  var tick, i, e;
  outer:
  for (tick = 0; tick < maxTicks; tick++) {
    if (tick >= 20 && (tick - 20) % 40 === 0) {
      var w = (tick - 20) / 40 + 1;
      wave = w;
      gold += Math.min(50, Math.floor(gold * 5 / 100)) + 10 + 2 * w;
      var comp = nextComp;
      nextComp = genWave(w + 1);
      var st = { tick: tick, wave: w, gold: gold, baseHp: baseHp, slots: [], enemies: enemies.map(view), nextWave: nextComp.slice() };
