      }
      var acts = strat.plan(st);
      if (Array.isArray(acts)) {
        for (i = 0; i < acts.length && i < 32; i++) {
          var a = acts[i];
          if (!a || typeof a !== "object") continue;
          var s = a.slot;
          if (typeof s !== "number" || s !== Math.floor(s) || s < 0 || s > 15) continue;
          var cur = turrets[s];
          if (a.op === "build") {
            if (cur || typeof a.type !== "string" || !Object.prototype.hasOwnProperty.call(TT, a.type)) continue;
            var c = TT[a.type].cost;
            if (gold < c) continue;
            gold -= c;
            cur = turrets[s] = { slot: s, type: a.type, tier: 1, spent: c, cd: 0, x: SLOTS[s][0] * 100 + 50, y: SLOTS[s][1] * 100 + 50, dmg: 0, range: 0 };
            tstats(cur);
            log.push([tick, "B", s, TT[a.type].idx]);
          } else if (a.op === "upgrade") {
            if (!cur || cur.tier >= 3) continue;
            var uc = TT[cur.type].cost * cur.tier;
            if (gold < uc) continue;
            gold -= uc; cur.spent += uc; cur.tier++; tstats(cur);
            log.push([tick, "U", s, cur.tier]);
          } else if (a.op === "sell") {
            if (!cur) continue;
            gold += Math.floor(cur.spent * 70 / 100);
            turrets[s] = null;
            log.push([tick, "S", s, 0]);
          }
        }
      }
      for (i = 0; i < comp.length; i++) queue.push({ tick: tick + 4 * i, wave: w, idx: i, type: comp[i] });
      queue.sort(function (p, q) { return p.tick - q.tick || p.wave - q.wave || p.idx - q.idx; });
    }
    var qn = 0;
    while (qn < queue.length && queue[qn].tick <= tick) {
      var q = queue[qn++];
      mkEnemy(q.type, q.wave, Math.floor(ET[q.type].hp * m(q.wave) / 1000), 0);
    }
    if (qn) queue.splice(0, qn);
