    var leaked = false;
    for (i = 0; i < enemies.length; i++) {
      e = enemies[i];
      e.progress += e.slow > 0 ? Math.floor(e.speed * 60 / 100) : e.speed;
      if (e.progress >= ROUTES[e.air].len) {
        baseHp -= e.leak; e.gone = true; leaked = true;
        log.push([tick, "L", e.id, baseHp]);
        if (fx) fx.push({ k: "L", id: e.id });
        if (baseHp <= 0) {
          fallTick = tick;
          log.push([tick, "F", wave, 0]);
          if (obs) { enemies = enemies.filter(function (z) { return !z.gone; }); obs({ tick: tick, wave: wave, gold: gold, baseHp: baseHp, enemies: enemies, turrets: turrets, fx: fx, nextWave: nextComp, fell: true }); }
          break outer;
        }
      } else place(e);
    }
    if (leaked) enemies = enemies.filter(function (z) { return !z.gone; });
    // age & heal
    for (i = 0; i < enemies.length; i++) {
      e = enemies[i];
      e.age++;
      if (e.type === "mender" && e.age % 20 === 0) {
        for (var j = 0; j < enemies.length; j++) {
          var o = enemies[j], hx = o.x - e.x, hy = o.y - e.y;
          if (hx * hx + hy * hy <= 22500) { o.hp = Math.min(o.maxHp, o.hp + Math.floor(o.maxHp * 8 / 100)); }
        }
        if (fx) fx.push({ k: "H", x: e.x, y: e.y });
      }
    }
    // fire
    for (var ts = 0; ts < 16; ts++) {
      var t = turrets[ts];
      if (!t) continue;
      if (t.cd > 0) { t.cd--; if (t.cd > 0) continue; }
      var d = TT[t.type], r2 = t.range * t.range, cands = [];
      for (i = 0; i < enemies.length; i++) {
        e = enemies[i];
        if (e.air ? !d.air : !d.ground) continue;
        var dx = e.x - t.x, dy = e.y - t.y;
        if (dx * dx + dy * dy <= r2) cands.push(e);
      }
      if (!cands.length) continue;
      var tg = null;
      if (hasTarget) {
        var rid = strat.target({ slot: ts, type: t.type, tier: t.tier, x: t.x, y: t.y, range: t.range }, cands.map(view));
        for (i = 0; i < cands.length; i++) if (cands[i].id === rid) { tg = cands[i]; break; }
      }
      if (!tg) {
        tg = cands[0];
        var br = ROUTES[tg.air].len - tg.progress;
        for (i = 1; i < cands.length; i++) { var rr = ROUTES[cands[i].air].len - cands[i].progress; if (rr < br) { br = rr; tg = cands[i]; } }
      }
      var hits;
      if (d.splash > 0) {
        hits = [];
        var s2 = d.splash * d.splash;
        for (i = 0; i < enemies.length; i++) {
          e = enemies[i];
          if (e.air ? !d.air : !d.ground) continue;
          var sx = e.x - tg.x, sy = e.y - tg.y;
          if (sx * sx + sy * sy <= s2) hits.push(e);
        }
      } else hits = [tg];
      var anyDead = false;
      for (i = 0; i < hits.length; i++) {
        e = hits[i];
        e.hp -= d.pierce ? t.dmg : Math.max(1, t.dmg - e.armor);
        if (d.slow > 0) e.slow = d.slow;
        if (e.hp <= 0) anyDead = true;
      }
      t.cd = d.period;
      if (fx) fx.push({ k: "X", slot: ts, type: d.idx, x: tg.x, y: tg.y, air: tg.air, id: tg.id });
      if (anyDead) {
        var n0 = enemies.length;
        for (i = 0; i < n0; i++) {
          e = enemies[i];
          if (e.hp > 0) continue;
          e.gone = true;
          gold += e.bounty;
          log.push([tick, "K", e.id, ts]);
          if (fx) fx.push({ k: "K", id: e.id, x: e.x, y: e.y, air: e.air, type: e.type });
          if (e.type === "splitter") {
            var sh = Math.max(1, Math.floor(e.maxHp / 4));
            for (var k3 = 0; k3 < 3; k3++) mkEnemy("splitling", e.wave, sh, e.progress);
          }
        }
        enemies = enemies.filter(function (z) { return !z.gone; });
      }
    }
    for (i = 0; i < enemies.length; i++) if (enemies[i].slow > 0) enemies[i].slow--;
    if (obs) { obs({ tick: tick, wave: wave, gold: gold, baseHp: baseHp, enemies: enemies, turrets: turrets, fx: fx, nextWave: nextComp, fell: false }); fx = []; }
  }
  var endTick = fallTick >= 0 ? fallTick : maxTicks;
  var str = JSON.stringify(log), h = 0x811c9dc5;
  for (i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193); }
  return { score: Math.round((endTick - 20) / 40 * 100) / 100, fallTick: fallTick, log: log, hash: (h >>> 0).toString(16).padStart(8, "0") };
}
