const A=() => ({ plan(s) { const a = []; let g = s.gold; for (const sl of s.slots) if (!sl.turret && g >= 50) { a.push({ op: "build", slot: sl.slot, type: "bolt" }); g -= 50; } return a; } });
const B=()=>({plan(s){return s.wave==1?[{op:"build",slot:3,type:"cannon"},{op:"build",slot:6,type:"frost"}]:s.wave==3?[{op:"upgrade",slot:3},{op:"build",slot:12,type:"flak"}]:s.wave==6?[{op:"build",slot:8,type:"lance"},{op:"sell",slot:6}]:[]}});
let r=rampartSimulate(A,42,12020);console.log(r.score,r.fallTick,r.log.length,r.hash,JSON.stringify(r.log.slice(0,7)));
r=rampartSimulate(B,7,12020);console.log(r.score,r.fallTick,r.log.length,r.hash);
