      if (anyDead) {
        var n0 = enemies.length;
        for (i = 0; i < n0; i++) {
          e = enemies[i];
          if (e.hp > 0) continue;
          e.gone = true;
          gold += e.bounty;
          log.push([tick, "K", e.id, ts]);
          if (fx) fx.push({ k: "K", id: e.id, x: e.x, y: e.y, air: e.air, type: e.type });
          if (e.type === "splitter") {
            var sh = Math.max(1, Math.floor(e.maxHp / 4));
            for (var k3 = 0; k3 < 3; k3++) mkEnemy("splitling", e.wave, sh, e.progress);
          }
        }
        enemies = enemies.filter(alive);
      }
    }
