// tuning version: makeCreate(ORDER, P) -> createStrategy
function makeCreate(ORDER, P) {
  return function createStrategy() {
    var NAMES = ["bolt", "cannon", "frost", "lance", "flak"];
    var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
    var DMG = { bolt: [26, 41, 65], cannon: [60, 96, 153], frost: [10, 16, 25], lance: [180, 288, 460], flak: [40, 64, 102] };
    var ptr = 0, mine = [];
    for (var i = 0; i < 16; i++) mine.push(null);
    function plan(state) {
      var acts = [], gold = state.gold, i;
      for (i = 0; i < 16; i++) { var t = state.slots[i].turret; mine[i] = t ? { type: t.type, tier: t.tier } : null; }
      var reserve = P.reserve && state.wave >= P.resFrom && state.wave < P.resTo ? P.reserve : 0;
      while (ptr < ORDER.length && acts.length < 32) {
        var it = ORDER[ptr], s = it[0], k = it[1], m = mine[s];
        if (k === -2) { if (m) { acts.push({ op: "sell", slot: s }); gold += Math.floor(0); mine[s] = null; } ptr++; continue; }
        if (k === -1) {
          if (!m || m.tier >= 3) { ptr++; continue; }
          var uc = COST[m.type] * m.tier;
          if (gold - uc < reserve) break;
          gold -= uc; m.tier++; acts.push({ op: "upgrade", slot: s }); ptr++; continue;
        }
        if (m) { ptr++; continue; }
        var c = COST[NAMES[k]];
        if (gold - c < reserve) break;
        gold -= c; mine[s] = { type: NAMES[k], tier: 1 }; acts.push({ op: "build", slot: s, type: NAMES[k] }); ptr++;
      }
      return acts;
    }
    function target(tur, c) {
      var n = c.length, i, j, e, best = -1, bv = -1e18, v;
      if (n === 1) return c[0].id;
      var type = tur.type, dmg = DMG[type][tur.tier - 1];
      if (type === "cannon" || type === "flak") {
        var r2 = type === "cannon" ? 8100 : 4900;
        var val = new Array(n);
        for (i = 0; i < n; i++) {
          e = c[i];
          var d = dmg - e.armor; if (d < 1) d = 1;
          if (d > e.hp) d = e.hp * P.killB;
          var L = e.air ? 2600 : 4600;
          val[i] = d * (1 + P.urg * (1 - e.remaining / L));
        }
        for (i = 0; i < n; i++) {
          var a = c[i]; v = 0;
          for (j = 0; j < n; j++) {
            var b = c[j], dx = a.x - b.x, dy = a.y - b.y;
            if (dx * dx + dy * dy <= r2) v += val[j];
          }
          v = v * 100000 - a.remaining;
          if (v > bv) { bv = v; best = a.id; }
        }
        return best;
      }
      if (type === "frost") {
        for (i = 0; i < n; i++) {
          e = c[i];
          v = (e.slowed ? 0 : 1e9) + e.hp * P.frostHp - e.remaining;
          if (v > bv) { bv = v; best = e.id; }
        }
        return best;
      }
      var pierce = type === "lance";
      for (i = 0; i < n; i++) {
        e = c[i];
        var dd = pierce ? dmg : dmg - e.armor; if (dd < 1) dd = 1;
        var kill = dd >= e.hp;
        if (dd > e.hp) dd = e.hp;
        var LL = e.air ? 2600 : 4600;
        v = dd * (1 + P.urg1 * (1 - e.remaining / LL));
        if (kill) v *= P.killB1;
        if (e.air) v *= P.airPref;
        if (pierce) v *= (1 + P.armW * e.armor);
        v = v * 100000 - e.remaining;
        if (v > bv) { bv = v; best = e.id; }
      }
      return best;
    }
    return { plan: plan, target: target };
  };
}
