load('sim.js'); load('strat.js');
var SEEDS = [101, 202, 303, 404, 505, 606, 707, 808, 909, 1010, 1111, 1212];
function evalOrder(order, P, seeds) {
  var tot = 0;
  for (var i = 0; i < seeds.length; i++) {
    var r = rampartSimulate(makeCreate(order, P), seeds[i], 12020);
    tot += (r.fallTick < 0 ? 12020 : r.fallTick);
  }
  return (tot / seeds.length - 20) / 40;
}
var order = [];
var slots = []; for (var i = 0; i < 16; i++) slots.push(null);
var t0 = Date.now();
for (var step = 0; step < 48; step++) {
  var best = null, bs = -1;
  for (var s = 0; s < 16; s++) {
    var cands = [];
    if (!slots[s]) { for (var k = 0; k < 5; k++) cands.push([s, k]); }
    else if (slots[s].tier < 3) cands.push([s, -1]);
    for (var c = 0; c < cands.length; c++) {
      var sc = evalOrder(order.concat([cands[c]]), P0, SEEDS);
      if (sc > bs) { bs = sc; best = cands[c]; }
    }
  }
  if (!best) break;
  order.push(best);
  if (best[1] >= 0) slots[best[0]] = { tier: 1 }; else slots[best[0]].tier++;
  print(step, JSON.stringify(best), bs.toFixed(2), ((Date.now() - t0) / 1000).toFixed(0) + 's');
}
print(JSON.stringify(order));

